-- Adds Portuguese gluten-free recipes. Safe to run repeatedly (INSERT OR IGNORE).
-- Apply: npx wrangler d1 execute <DB> --remote --file=seed/migrate_pt_recipes.sql
INSERT OR IGNORE INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('arroz-de-pato','Arroz de Pato (Portuguese Duck Rice)','Classic Portuguese baked duck rice — shredded duck and chouriço folded through rice cooked in the duck broth, then baked until the top crisps.','portuguese','medium',90,20,110,6,560,1,0,0,1,0,'duck',0.55,10,0,'[{"name": "Duck legs", "quantity": 4, "unit": "unit", "unit_norm": "unit", "category": "meat"}, {"name": "Chouriço", "quantity": 1, "unit": "unit", "unit_norm": "unit", "category": "meat"}, {"name": "Smoked bacon", "quantity": 100, "unit": "g", "unit_norm": "g", "category": "meat"}, {"name": "Long-grain rice", "quantity": 3, "unit": "cups", "unit_norm": "cup", "category": "pantry"}, {"name": "Yellow onion", "quantity": 1, "unit": "unit", "unit_norm": "unit", "category": "produce"}, {"name": "Garlic", "quantity": 3, "unit": "cloves", "unit_norm": "clove", "category": "produce"}, {"name": "Bay leaf", "quantity": 2, "unit": "unit", "unit_norm": "unit", "category": "produce"}, {"name": "Orange", "quantity": 1, "unit": "unit", "unit_norm": "unit", "category": "produce"}, {"name": "Olive oil", "quantity": 2, "unit": "tbsp", "unit_norm": "tbsp", "category": "pantry"}, {"name": "Coarse salt", "quantity": 1, "unit": "tsp", "unit_norm": "tbsp", "category": "pantry"}]','["Put the duck legs, chouriço, bacon, half an onion, bay, a strip of orange peel and salt in a large pot. Cover with water and simmer 50–60 min until the duck is tender.", "Lift out the meats. Strain and reserve the broth. Shred the duck (discard skin and bones); slice the chouriço and bacon.", "Soften the remaining chopped onion and garlic in olive oil. Add the rice and stir 1 min.", "Add 6 cups of the reserved broth (top up with water if short), bring to a boil, then simmer covered ~15 min until the rice is just done but a little wet.", "Heat oven to 200°C (400°F). Fold most of the duck into the rice; spread in a baking dish.", "Top with the sliced chouriço, bacon and remaining duck. Bake 15–20 min until the top is golden and crisp.", "Rest 5 min and serve with orange wedges."]','Portuguese classic (added for Groceree)');
INSERT OR IGNORE INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('caldo-verde','Caldo Verde (Portuguese Greens & Potato Soup)','Silky potato soup with thinly shredded collard greens and slices of chouriço — Portugal''s most-loved everyday soup. Naturally gluten-free and very easy.','portuguese','easy',30,10,40,6,260,1,0,0,1,0,'pork',0.8,7,1,'[{"name": "Potatoes", "quantity": 700, "unit": "g", "unit_norm": "g", "category": "produce"}, {"name": "Collard greens (couve galega) or kale", "quantity": 300, "unit": "g", "unit_norm": "g", "category": "produce"}, {"name": "Chouriço", "quantity": 1, "unit": "unit", "unit_norm": "unit", "category": "meat"}, {"name": "Yellow onion", "quantity": 1, "unit": "unit", "unit_norm": "unit", "category": "produce"}, {"name": "Garlic", "quantity": 2, "unit": "cloves", "unit_norm": "clove", "category": "produce"}, {"name": "Olive oil", "quantity": 3, "unit": "tbsp", "unit_norm": "tbsp", "category": "pantry"}, {"name": "Coarse salt", "quantity": 1, "unit": "tsp", "unit_norm": "tbsp", "category": "pantry"}]','["Soften the chopped onion and garlic in olive oil in a large pot.", "Add peeled, chunked potatoes and ~1.5 L water with salt. Boil until potatoes are very soft, ~20 min.", "Meanwhile slice the chouriço and simmer the slices in a little water 5 min (skim the fat), then set aside.", "Blend the potato base smooth with a stick blender.", "Shred the greens as finely as possible. Stir into the soup and simmer 5–8 min until just tender (don''t overcook).", "Serve topped with the chouriço slices and a thread of olive oil."]','Portuguese classic (added for Groceree)');
INSERT OR IGNORE INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('frango-piri-piri','Frango Grelhado Piri-Piri (Grilled Piri-Piri Chicken)','Butterflied chicken marinated in garlic, lemon and piri-piri, then grilled. Fast, gluten-free, dairy-free and a family favourite.','portuguese','easy',30,15,45,4,430,1,0,0,1,0,'chicken',0.8,7,0,'[{"name": "Whole chicken, butterflied (or thighs)", "quantity": 1.4, "unit": "kg", "unit_norm": "g", "category": "meat"}, {"name": "Garlic", "quantity": 4, "unit": "cloves", "unit_norm": "clove", "category": "produce"}, {"name": "Piri-piri / hot chilli", "quantity": 2, "unit": "unit", "unit_norm": "unit", "category": "produce"}, {"name": "Lemon", "quantity": 1, "unit": "unit", "unit_norm": "unit", "category": "produce"}, {"name": "Sweet paprika", "quantity": 1, "unit": "tbsp", "unit_norm": "tbsp", "category": "pantry"}, {"name": "Olive oil", "quantity": 3, "unit": "tbsp", "unit_norm": "tbsp", "category": "pantry"}, {"name": "Coarse salt", "quantity": 1, "unit": "tsp", "unit_norm": "tbsp", "category": "pantry"}]','["Blend garlic, chilli, lemon juice, paprika, olive oil and salt into a marinade.", "Coat the butterflied chicken and rest at least 30 min (overnight is better).", "Grill or roast at 220°C, skin-side first, ~15 min per side, basting with the marinade, until juices run clear.", "Rest 5 min, cut up and serve with lemon and a salad or rice."]','Portuguese classic (added for Groceree)');
INSERT OR IGNORE INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('bacalhau-a-bras','Bacalhau à Brás (Salt Cod with Eggs & Potato)','Shredded salt cod tossed with onions, matchstick potatoes and eggs until just creamy — a Lisbon classic. Naturally gluten-free.','portuguese','medium',30,20,50,4,520,1,0,1,1,0,'fish',0.55,8,0,'[{"name": "Salt cod (bacalhau), soaked & flaked", "quantity": 500, "unit": "g", "unit_norm": "g", "category": "seafood"}, {"name": "Potatoes, cut into thin matchsticks", "quantity": 500, "unit": "g", "unit_norm": "g", "category": "produce"}, {"name": "Eggs", "quantity": 6, "unit": "unit", "unit_norm": "unit", "category": "dairy"}, {"name": "Yellow onion", "quantity": 2, "unit": "unit", "unit_norm": "unit", "category": "produce"}, {"name": "Garlic", "quantity": 3, "unit": "cloves", "unit_norm": "clove", "category": "produce"}, {"name": "Black olives", "quantity": 12, "unit": "unit", "unit_norm": "unit", "category": "pantry"}, {"name": "Parsley", "quantity": 1, "unit": "handful", "unit_norm": "unit", "category": "produce"}, {"name": "Olive oil", "quantity": 4, "unit": "tbsp", "unit_norm": "tbsp", "category": "pantry"}]','["Fry the potato matchsticks in oil until golden (or use ready straw potatoes). Drain.", "Soften sliced onion and garlic in olive oil. Add the flaked, soaked cod and warm through 3–4 min.", "Fold in the fried potatoes.", "Beat the eggs, pour over and stir gently over low heat until just set and creamy — do not overcook.", "Off the heat, scatter olives and chopped parsley. Serve immediately."]','Portuguese classic (added for Groceree)');
INSERT OR IGNORE INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sardinhas-assadas','Sardinhas Assadas (Grilled Sardines)','Whole sardines simply salted and grilled — the taste of a Portuguese summer. Gluten-free, dairy-free, very easy.','portuguese','easy',12,10,22,4,310,1,0,1,1,0,'fish',0.8,6,0,'[{"name": "Fresh sardines", "quantity": 12, "unit": "unit", "unit_norm": "unit", "category": "seafood"}, {"name": "Coarse sea salt", "quantity": 3, "unit": "tbsp", "unit_norm": "tbsp", "category": "pantry"}, {"name": "Bell peppers", "quantity": 2, "unit": "unit", "unit_norm": "unit", "category": "produce"}, {"name": "Boiling potatoes", "quantity": 600, "unit": "g", "unit_norm": "g", "category": "produce"}, {"name": "Olive oil", "quantity": 2, "unit": "tbsp", "unit_norm": "tbsp", "category": "pantry"}, {"name": "Lemon", "quantity": 1, "unit": "unit", "unit_norm": "unit", "category": "produce"}]','["Salt the whole sardines generously and leave 30–60 min; pat off excess salt.", "Boil the potatoes whole until tender; keep warm.", "Grill the peppers until charred, then peel and dress with olive oil.", "Grill the sardines over high heat ~3 min per side until the skin crisps.", "Serve with the potatoes, peppers and lemon wedges."]','Portuguese classic (added for Groceree)');
INSERT OR IGNORE INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('carne-porco-alentejana','Carne de Porco à Alentejana (Pork with Clams)','Pork marinated in garlic and red-pepper paste, seared and finished with clams and fried potato cubes. Surf-and-turf Alentejo style, naturally gluten-free.','portuguese','medium',40,30,70,4,540,1,0,0,1,0,'pork',0.55,10,0,'[{"name": "Pork shoulder, cubed", "quantity": 700, "unit": "g", "unit_norm": "g", "category": "meat"}, {"name": "Clams, purged", "quantity": 600, "unit": "g", "unit_norm": "g", "category": "seafood"}, {"name": "Massa de pimentão (red pepper paste)", "quantity": 2, "unit": "tbsp", "unit_norm": "tbsp", "category": "pantry"}, {"name": "Garlic", "quantity": 4, "unit": "cloves", "unit_norm": "clove", "category": "produce"}, {"name": "White wine", "quantity": 150, "unit": "ml", "unit_norm": "ml", "category": "pantry"}, {"name": "Bay leaf", "quantity": 2, "unit": "unit", "unit_norm": "unit", "category": "produce"}, {"name": "Potatoes, cubed & fried", "quantity": 500, "unit": "g", "unit_norm": "g", "category": "produce"}, {"name": "Coriander", "quantity": 1, "unit": "handful", "unit_norm": "unit", "category": "produce"}, {"name": "Lemon", "quantity": 1, "unit": "unit", "unit_norm": "unit", "category": "produce"}, {"name": "Olive oil", "quantity": 3, "unit": "tbsp", "unit_norm": "tbsp", "category": "pantry"}]','["Marinate the pork cubes with red-pepper paste, crushed garlic, white wine and bay for at least 2 h.", "Drain (keep the marinade). Sear the pork in olive oil until browned; add the marinade and simmer until tender, ~20 min.", "Add the purged clams, cover, and cook just until they open (discard any that don''t), ~5 min.", "Fold in the fried potato cubes.", "Finish with chopped coriander and lemon. Serve hot."]','Portuguese classic (added for Groceree)');
